"""Short actual turn-to-action checks; geometric jumps are reported as measurements."""
from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/visual-frame';O.mkdir(parents=True,exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready&&INK.FrameBridge')
 runs=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,V=INK.VisualFrame,out=[];const names=['rearArm','frontArm','rearLeg','frontLeg'],dist=(a,b)=>Math.hypot(...a.map((v,i)=>v-b[i])),det=m=>m[0]*m[3]-m[1]*m[2];
 for(const id of ['ryu','mai'])for(const delay of [0,3,6])for(const action of ['sLP','sHK','block','hit']){
 A.start(id,'ryu','training','classic',41);G.paused=false;document.getElementById('dummy').value='idle';document.getElementById('autohp').checked=false;A.teleport(0,600);A.teleport(1,950);A.step(2);A.teleport(1,230);A.step(1+delay);const f=A.fighters[0],before=V.get(A.visualPose(f)),phase=INK.FacingMotion.sample(f,f._inkVisualClock),traces=[];let accepted=true;
 if(action==='block'||action==='hit'){A.teleport(1,f.x-140);if(action==='block')A.press(0,'right');accepted=A.tryMove(1,'sMP');}else accepted=A.tryMove(0,action);
 const endJumpXY=Object.fromEntries(names.map(n=>[n,0]));let last=before,maxJump=0,minDet=Infinity,maxLengthChange=0,activeExact=true,activeErrorXYZ=0,activeErrorXY=0,supportJumpXY=0,bridgeMinDet=null,event=null,finite=true;
 for(let i=0;i<30;i++){A.step();const frame=V.get(A.visualPose(f));if(!frame)continue;let jump=0,change=0,worstEnd=null;for(const name of names){const chain=frame.joints3D[name],prior=last.joints3D[name];endJumpXY[name]=Math.max(endJumpXY[name],Math.hypot(chain[2][0]-prior[2][0],chain[2][1]-prior[2][1]));const delta=dist(chain[2],prior[2]);if(delta>jump){jump=delta;worstEnd={name,joint:2,from:prior[2].slice(),to:chain[2].slice(),fromMode:last.mode,toMode:frame.mode,fromBridge:last.bridge?.age??null,toBridge:frame.bridge?.age??null,screenDistance:Math.hypot(chain[2][0]-prior[2][0],chain[2][1]-prior[2][1])};}for(let j=0;j<2;j++)change=Math.max(change,Math.abs(dist(chain[j],chain[j+1])-dist(prior[j],prior[j+1])));minDet=Math.min(minDet,Math.abs(det(frame.endFrames[name])));if(frame.bridge){bridgeMinDet=Math.min(bridgeMinDet??Infinity,Math.abs(det(frame.endFrames[name])));if(name.endsWith('Leg')&&!INK.FrameBridge.contactChains(f).includes(name))supportJumpXY=Math.max(supportJumpXY,Math.hypot(chain[2][0]-prior[2][0],chain[2][1]-prior[2][1]));}finite&&=chain.every(q=>q.every(Number.isFinite));}maxJump=Math.max(maxJump,jump);maxLengthChange=Math.max(maxLengthChange,change);if(f.attack&&f.attack.t>=f.attack.m.startup){const view=Object.create(f);view._inkFrameTransition=null;const target=V.get(A.visualPose(view));for(const name of INK.FrameBridge.contactChains(f))for(let j=0;j<3;j++){const a=frame.joints3D[name][j],b=target.joints3D[name][j],xyz=dist(a,b),xy=Math.hypot(a[0]-b[0],a[1]-b[1]);activeErrorXYZ=Math.max(activeErrorXYZ,xyz);activeErrorXY=Math.max(activeErrorXY,xy);activeExact&&=xyz<1e-7&&xy<1e-7;}}if(G.lastCombatEvent?.defender===0)event=G.lastCombatEvent.type;traces.push({i,state:f.state,t:f.attack?.t??null,bridge:frame.bridge?.age??null,jump,change,worstEnd});last=frame;}
 G.paused=true;const state=JSON.stringify(A.combatState()),frame=JSON.stringify(V.get(A.visualPose(f)));for(let i=0;i<8;i++)A.renderFraction(i%3/2);const pure=state===JSON.stringify(A.combatState())&&frame===JSON.stringify(V.get(A.visualPose(f)));
 out.push({id,delay,action,phase:phase?.progress,accepted,event,finite,pure,activeExact,activeErrorXYZ,activeErrorXY,supportJumpXY,bridgeMinDet,endJumpXY,maxJump,minEndDet:minDet,maxLengthChange,worst:traces.sort((a,b)=>b.jump-a.jump).slice(0,3)});
 }return out;}''');b.close()
report={'htmlSha256':hashlib.sha256(html).hexdigest(),'runs':runs,'errors':errors,'note':'No broad visual-quality acceptance threshold; jumps/determinants/length changes are explicit measurements.'};(O/'bridge.json').write_text(json.dumps(report,indent=2)+'\n')
for r in runs:print(r['id'],r['delay'],r['action'],'event',r['event'],'jump',round(r['maxJump'],2),'det',round(r['minEndDet'],5),'lengthdelta',round(r['maxLengthChange'],2))
assert not errors and all(r['finite'] and r['pure'] and r['accepted'] and r['activeExact'] and (r['event']==r['action'] if r['action'] in ['hit','block'] else True) for r in runs),errors
